text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به إلى بيانات المستخدمين، تقوم المنصة بتقييم الواقعة واتخاذ ما تراه مناسباً، مع الاحتفاظ بحقها الكامل في تحديد ما إذا كان إشعار الجهات المختصة أو المستخدمين ملائماً للظروف وحسب التوقيت الذي يرتئيه فريق العمل."
    },
    {
      "slot": "p2",
      "text": "تحتفظ شركة الأفق الرقمي بجميع سجلات ومعلومات المستخدمين ضمن أرشيفها الرقمي لأغراض التطوير المستقبلي والتحليل الإحصائي دون وجود أي التزام بإتلافها أو محوها نهائياً، حتى بعد انتهاء العلاقة التعاقدية أو إغلاق الحساب."
    },
    {
      "slot": "p3",
      "text": "قبل الشروع في إنشاء الحساب وجمع البيانات، يتيح الموقع للمستخدمين الإطلاع على هذه السياسة التي توضح بدقة طبيعة المعلومات المجمعة، وأغراض معالجتها، وآليات تخزينها وحمايتها، إضافة إلى بيان كافة الحقوق المقررة وكيفية ممارستها عملياً."
    },
    {
      "slot": "p4",
      "text": "تسعى المنصة إلى جمع القدر الملائم من البيانات الذي تراه كافياً لتشغيل الحسابات وتقديم الخدمات بالشكل المطلوب بناءً على طبيعة التفاعل المتاح للمستخدم."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية ورسوم الاشتراك المرتجعة للسياسات التجارية المعتمدة من إدارة المنصة وقت إتمام عملية الدفع.",
    "تبدأ المدة التعاقدية لهذه الاتفاقية فور إتمام التسجيل وتستمر حتى يقوم أحد الطرفين بإنهاء الحساب وفق الآليات المتاحة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن انقطاع الخدمة المؤقت أو الأعطال التقنية خارجة الإرادة.",
    "تُفسر هذه الشروط وتخضع لأنظمة وقوانين المملكة العربية السعودية، وتختص المحاكم المختصة بالفصل في أي نزاع ينشأ عنها.",
    "تعني المصطلحات الواردة في هذه الوثيقة المعاني المتعارف عليها تجارياً ما لم يقتضِ السياق خلاف ذلك.",
    "تظل كافة حقوق الملكية الفكرية والعلامات التجارية والتصميمات الخاصة بالمنصة ملكية حصرية لشركة الأفق الرقمي ولا يجوز استخدامها دون إذن خطي مسبق."
  ]
}
